# -------------------------------------------------------------------
# Quality-report helpers
# -------------------------------------------------------------------

empty_checks <- function() {
  data.frame(
    check = character(),
    passed = logical(),
    actual = character(),
    expected = character(),
    stringsAsFactors = FALSE
  )
}

new_check <- function(name, passed, actual, expected) {
  data.frame(
    check = name,
    passed = isTRUE(passed),
    actual = as.character(actual),
    expected = as.character(expected),
    stringsAsFactors = FALSE
  )
}

# Accumulator so every validation function records results in one place and
# the same evidence can both gate the run and be written to disk.
check_collector <- function() {
  collector <- new.env(parent = emptyenv())
  collector$rows <- list()

  collector$add <- function(name, passed, actual, expected) {
    collector$rows[[length(collector$rows) + 1L]] <- new_check(
      name,
      passed,
      actual,
      expected
    )
    invisible(NULL)
  }

  collector$frame <- function() {
    if (length(collector$rows) == 0L) {
      return(empty_checks())
    }
    do.call(rbind, collector$rows)
  }

  collector
}

combine_checks <- function(...) {
  frames <- Filter(
    function(frame) !is.null(frame) && nrow(frame) > 0L,
    list(...)
  )
  if (length(frames) == 0L) {
    return(empty_checks())
  }
  do.call(rbind, frames)
}

within_tolerance <- function(actual, expected, tolerance = RELATIVE_TOLERANCE) {
  if (length(actual) != length(expected)) {
    return(FALSE)
  }
  if (any(is.na(actual)) || any(is.na(expected))) {
    return(FALSE)
  }
  all(abs(actual - expected) <= tolerance * pmax(1, abs(expected)))
}

relative_difference <- function(actual, expected) {
  ifelse(
    is.na(actual) | is.na(expected),
    NA_real_,
    abs(actual - expected) / pmax(1, abs(expected))
  )
}

format_value <- function(value, digits = 6) {
  if (length(value) == 0L) {
    return(character())
  }
  formatC(as.numeric(value), format = "f", digits = digits)
}

describe_vector <- function(values) {
  paste(values, collapse = "|")
}

# -------------------------------------------------------------------
# Environment and paths
# -------------------------------------------------------------------

find_project_root <- function(start_dir = getwd()) {
  override <- Sys.getenv("R_ANALYSIS_PROJECT_ROOT", unset = "")

  if (nzchar(override)) {
    resolved <- normalizePath(override, winslash = "/", mustWork = TRUE)

    if (!file.exists(file.path(resolved, "pyproject.toml"))) {
      stop(
        paste(
          "R_ANALYSIS_PROJECT_ROOT does not contain pyproject.toml:",
          resolved
        ),
        call. = FALSE
      )
    }

    return(resolved)
  }

  current <- normalizePath(start_dir, winslash = "/", mustWork = TRUE)

  repeat {
    if (
      file.exists(file.path(current, "pyproject.toml")) &&
        dir.exists(file.path(current, "docs"))
    ) {
      return(current)
    }

    parent <- dirname(current)

    if (identical(parent, current)) {
      stop(
        paste0(
          "Could not locate the project root above ",
          normalizePath(start_dir, winslash = "/", mustWork = FALSE),
          ". Run the workflow from inside the repository or set ",
          "R_ANALYSIS_PROJECT_ROOT."
        ),
        call. = FALSE
      )
    }

    current <- parent
  }
}

resolve_paths <- function(project_root) {
  input_override <- Sys.getenv("R_ANALYSIS_INPUT_DIR", unset = "")

  input_dir <- if (nzchar(input_override)) {
    input_override
  } else {
    file.path(project_root, "data", "analysis")
  }

  output_override <- Sys.getenv("R_ANALYSIS_OUTPUT_DIR", unset = "")

  output_dir <- if (nzchar(output_override)) {
    output_override
  } else {
    file.path(input_dir, "r")
  }

  list(
    project_root = project_root,
    input_dir = normalizePath(input_dir, winslash = "/", mustWork = FALSE),
    output_dir = normalizePath(output_dir, winslash = "/", mustWork = FALSE),
    plot_dir = normalizePath(
      file.path(output_dir, "plots"),
      winslash = "/",
      mustWork = FALSE
    )
  )
}

check_required_packages <- function() {
  available <- vapply(
    REQUIRED_PACKAGES,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )

  missing_packages <- REQUIRED_PACKAGES[!available]

  if (length(missing_packages) > 0L) {
    stop(
      paste(
        "Missing required R packages:",
        paste(missing_packages, collapse = ", ")
      ),
      call. = FALSE
    )
  }

  data.frame(
    package = REQUIRED_PACKAGES,
    version = vapply(
      REQUIRED_PACKAGES,
      function(package) as.character(utils::packageVersion(package)),
      character(1)
    ),
    stringsAsFactors = FALSE
  )
}

record_environment <- function(paths, packages) {
  pandoc_version <- tryCatch(
    {
      if (
        requireNamespace("rmarkdown", quietly = TRUE) &&
          isTRUE(rmarkdown::pandoc_available())
      ) {
        as.character(rmarkdown::pandoc_version())
      } else {
        "not available"
      }
    },
    error = function(condition) "not available"
  )

  environment <- rbind(
    data.frame(
      item = c(
        "r_version",
        "platform",
        "pandoc_version",
        "run_date",
        "input_dir"
      ),
      value = c(
        R.version.string,
        R.version$platform,
        pandoc_version,
        format(Sys.time(), tz = "UTC", usetz = TRUE),
        paths$input_dir
      ),
      stringsAsFactors = FALSE
    ),
    data.frame(
      item = paste0("package_", packages$package),
      value = packages$version,
      stringsAsFactors = FALSE
    )
  )

  readr::write_csv(
    environment,
    file.path(paths$output_dir, "r_environment.csv")
  )

  environment
}

# -------------------------------------------------------------------
# Input loading and validation
# -------------------------------------------------------------------

load_inputs <- function(input_dir) {
  files <- file.path(input_dir, INPUT_FILES)
  names(files) <- names(INPUT_FILES)

  present <- vapply(files, file.exists, logical(1))

  data <- list()

  for (key in names(INPUT_FILES)) {
    if (isTRUE(present[[key]])) {
      data[[key]] <- readr::read_csv(
        files[[key]],
        show_col_types = FALSE,
        progress = FALSE
      )
    }
  }

  list(files = files, present = present, data = data)
}

validate_inputs <- function(loaded, checks) {
  checks$add(
    "required_input_files_present",
    all(loaded$present),
    sum(loaded$present),
    length(loaded$present)
  )

  for (key in names(REQUIRED_COLUMNS)) {
    frame <- loaded$data[[key]]
    required <- REQUIRED_COLUMNS[[key]]

    if (is.null(frame)) {
      checks$add(
        paste0(key, "_columns_present"),
        FALSE,
        "file missing",
        describe_vector(required)
      )
      checks$add(
        paste0(key, "_not_empty"),
        FALSE,
        "file missing",
        "> 0"
      )
      next
    }

    missing_columns <- setdiff(required, names(frame))

    checks$add(
      paste0(key, "_columns_present"),
      length(missing_columns) == 0L,
      if (length(missing_columns) == 0L) {
        length(required)
      } else {
        paste(missing_columns, collapse = ",")
      },
      describe_vector(required)
    )

    if (length(missing_columns) == 0L) {
      missing_values <- sum(is.na(frame[required]))
      checks$add(
        paste0(key, "_no_missing_values"),
        missing_values == 0L,
        missing_values,
        0
      )
    }

    checks$add(
      paste0(key, "_not_empty"),
      nrow(frame) > 0L,
      nrow(frame),
      "> 0"
    )
  }

  # Downstream checks index required columns, so a missing file or a missing
  # column must stop the run here rather than fail later with an R error.
  incomplete_columns <- vapply(
    names(REQUIRED_COLUMNS),
    function(key) {
      frame <- loaded$data[[key]]
      is.null(frame) ||
        length(setdiff(REQUIRED_COLUMNS[[key]], names(frame))) > 0L
    },
    logical(1)
  )

  if (any(!loaded$present) || any(incomplete_columns)) {
    checks$add(
      "inputs_ready_for_analysis",
      FALSE,
      describe_vector(c(
        names(INPUT_FILES)[!loaded$present],
        names(incomplete_columns)[incomplete_columns]
      )),
      "all required inputs present with their required columns"
    )
    return(invisible(FALSE))
  }

  demand <- loaded$data$demand
  variability <- loaded$data$variability
  validation_results <- loaded$data$validation_results

  checks$add(
    "store_ids_unique_in_demand",
    dplyr::n_distinct(demand$store_id) == nrow(demand),
    dplyr::n_distinct(demand$store_id),
    nrow(demand)
  )

  checks$add(
    "store_ids_unique_in_variability",
    dplyr::n_distinct(variability$store_id) == nrow(variability),
    dplyr::n_distinct(variability$store_id),
    nrow(variability)
  )

  reference_stores <- sort(unique(demand$store_id))
  compared_stores <- c(
    variability = identical(
      sort(unique(variability$store_id)),
      reference_stores
    ),
    scenarios = identical(
      sort(unique(loaded$data$scenarios$store_id)),
      reference_stores
    ),
    forecast_scenarios = identical(
      sort(unique(loaded$data$forecast_scenarios$store_id)),
      reference_stores
    ),
    forecast_errors = identical(
      sort(unique(loaded$data$forecast_errors$store_id)),
      reference_stores
    ),
    densification = identical(
      sort(unique(loaded$data$densification$store_id)),
      reference_stores
    ),
    validation_results = identical(
      sort(unique(validation_results$store_id)),
      reference_stores
    )
  )

  checks$add(
    "store_sets_identical_across_inputs",
    all(compared_stores),
    describe_vector(names(compared_stores)[!compared_stores]),
    "same store set across demand, variability, scenarios, forecast scenarios, forecast errors, densification and validation results"
  )

  checks$add(
    "training_days_positive",
    all(demand$training_days > 0),
    min(demand$training_days),
    "> 0"
  )

  checks$add(
    "demand_values_non_negative",
    all(demand$mean_daily_demand >= 0) &&
      all(demand$median_daily_demand >= 0) &&
      all(demand$min_daily_demand >= 0) &&
      all(demand$max_daily_demand >= 0) &&
      all(demand$total_quantity >= 0),
    min(demand$min_daily_demand),
    ">= 0"
  )

  checks$add(
    "variability_values_non_negative",
    all(variability$mean_daily_demand >= 0) &&
      all(variability$std_daily_demand >= 0) &&
      all(variability$variance_daily_demand >= 0) &&
      all(variability$p90_daily_demand >= 0) &&
      all(variability$p95_daily_demand >= 0) &&
      all(variability$p99_daily_demand >= 0),
    min(variability$std_daily_demand),
    ">= 0"
  )

  checks$add(
    "percentiles_ordered",
    all(variability$p90_daily_demand <= variability$p95_daily_demand) &&
      all(variability$p95_daily_demand <= variability$p99_daily_demand),
    "p90 <= p95 <= p99",
    "p90 <= p95 <= p99"
  )

  mean_from_total <- demand$total_quantity / demand$training_days
  checks$add(
    "mean_matches_total_over_days",
    within_tolerance(
      demand$mean_daily_demand,
      mean_from_total,
      RELATIVE_TOLERANCE
    ),
    format_value(
      max(relative_difference(demand$mean_daily_demand, mean_from_total)),
      12
    ),
    paste("<=", RELATIVE_TOLERANCE)
  )

  variance_from_std <- variability$std_daily_demand^2
  checks$add(
    "variance_matches_standard_deviation",
    within_tolerance(
      variability$variance_daily_demand,
      variance_from_std,
      RELATIVE_TOLERANCE
    ),
    format_value(
      max(relative_difference(
        variability$variance_daily_demand,
        variance_from_std
      )),
      12
    ),
    paste("<=", RELATIVE_TOLERANCE)
  )

  coefficient_from_ratio <- variability$std_daily_demand /
    variability$mean_daily_demand

  joined_coefficient <- dplyr::inner_join(
    demand %>% dplyr::select(store_id, demand_cv = coefficient_of_variation),
    variability %>%
      dplyr::select(store_id, variability_cv = coefficient_of_variation),
    by = "store_id"
  )

  joined_coefficient$difference <- relative_difference(
    joined_coefficient$variability_cv,
    joined_coefficient$demand_cv
  )

  checks$add(
    "coefficient_of_variation_matches_ratio",
    within_tolerance(
      variability$coefficient_of_variation,
      coefficient_from_ratio,
      RELATIVE_TOLERANCE
    ) &&
      all(joined_coefficient$difference <= RELATIVE_TOLERANCE),
    format_value(
      max(c(
        max(relative_difference(
          variability$coefficient_of_variation,
          coefficient_from_ratio
        )),
        max(joined_coefficient$difference)
      )),
      12
    ),
    paste("<=", RELATIVE_TOLERANCE)
  )

  checks$add(
    "validation_results_non_negative",
    all(validation_results$rmse >= 0) &&
      all(validation_results$mape_percent >= 0),
    min(validation_results$rmse),
    ">= 0"
  )

  checks$add(
    "inputs_ready_for_analysis",
    all(checks$frame()$passed),
    sum(checks$frame()$passed),
    nrow(checks$frame())
  )

  invisible(all(checks$frame()$passed))
}

# -------------------------------------------------------------------
# Store-level demand analysis
# -------------------------------------------------------------------

build_store_analysis <- function(demand, variability) {
  demand %>%
    dplyr::select(
      store_id,
      training_days,
      total_quantity,
      mean_daily_demand,
      median_daily_demand,
      min_daily_demand,
      max_daily_demand,
      coefficient_of_variation
    ) %>%
    dplyr::left_join(
      variability %>%
        dplyr::select(
          store_id,
          std_daily_demand,
          variance_daily_demand,
          p90_daily_demand,
          p95_daily_demand,
          p99_daily_demand
        ),
      by = "store_id"
    ) %>%
    dplyr::arrange(dplyr::desc(mean_daily_demand))
}

# -------------------------------------------------------------------
# Scenario validation
# -------------------------------------------------------------------

validate_scenario_family <- function(
  frame,
  prefix,
  level_column,
  spread_column
) {
  checks <- empty_checks()

  store_count <- dplyr::n_distinct(frame$store_id)
  expected_rows <- store_count * length(SCENARIO_LEAD_TIMES) *
    length(SCENARIO_SERVICE_LEVELS)

  expected_lead_time_demand <- frame[[level_column]] * frame$lead_time_days
  expected_safety_stock <- frame$z_value *
    frame[[spread_column]] *
    sqrt(frame$lead_time_days)

  checks <- rbind(
    checks,
    new_check(
      paste0(prefix, "_scenario_coverage_complete"),
      nrow(frame) == expected_rows &&
        dplyr::n_distinct(
          frame$store_id,
          frame$lead_time_days,
          frame$service_level
        ) == expected_rows,
      nrow(frame),
      expected_rows
    ),
    new_check(
      paste0(prefix, "_lead_times_complete"),
      setequal(unique(frame$lead_time_days), SCENARIO_LEAD_TIMES),
      describe_vector(sort(unique(frame$lead_time_days))),
      describe_vector(SCENARIO_LEAD_TIMES)
    ),
    new_check(
      paste0(prefix, "_service_levels_complete"),
      setequal(unique(frame$service_level), SCENARIO_SERVICE_LEVELS),
      describe_vector(sort(unique(frame$service_level))),
      describe_vector(SCENARIO_SERVICE_LEVELS)
    ),
    new_check(
      paste0(prefix, "_service_level_z_values_match"),
      within_tolerance(
        frame$z_value,
        stats::qnorm(frame$service_level),
        1e-9
      ),
      format_value(
        max(abs(frame$z_value - stats::qnorm(frame$service_level))),
        12
      ),
      paste("<=", 1e-9)
    ),
    new_check(
      paste0(prefix, "_expected_lead_time_demand_formula_holds"),
      within_tolerance(
        frame$expected_lead_time_demand,
        expected_lead_time_demand,
        RELATIVE_TOLERANCE
      ),
      format_value(
        max(relative_difference(
          frame$expected_lead_time_demand,
          expected_lead_time_demand
        )),
        12
      ),
      paste("<=", RELATIVE_TOLERANCE)
    ),
    new_check(
      paste0(prefix, "_safety_stock_formula_holds"),
      within_tolerance(
        frame$safety_stock,
        expected_safety_stock,
        RELATIVE_TOLERANCE
      ),
      format_value(
        max(relative_difference(frame$safety_stock, expected_safety_stock)),
        12
      ),
      paste("<=", RELATIVE_TOLERANCE)
    ),
    new_check(
      paste0(prefix, "_reorder_point_formula_holds"),
      within_tolerance(
        frame$reorder_point,
        frame$expected_lead_time_demand + frame$safety_stock,
        RELATIVE_TOLERANCE
      ),
      format_value(
        max(relative_difference(
          frame$reorder_point,
          frame$expected_lead_time_demand + frame$safety_stock
        )),
        12
      ),
      paste("<=", RELATIVE_TOLERANCE)
    ),
    new_check(
      paste0(prefix, "_safety_stock_non_negative"),
      all(frame$safety_stock >= 0),
      min(frame$safety_stock),
      ">= 0"
    ),
    new_check(
      paste0(prefix, "_reorder_point_covers_lead_time_demand"),
      all(frame$reorder_point >= frame$expected_lead_time_demand),
      min(frame$reorder_point - frame$expected_lead_time_demand),
      ">= 0"
    )
  )

  safety_ordered <- frame %>%
    dplyr::group_by(store_id, lead_time_days) %>%
    dplyr::arrange(service_level, .by_group = TRUE) %>%
    dplyr::summarise(
      monotone = all(diff(safety_stock) > 0),
      .groups = "drop"
    )

  checks <- rbind(
    checks,
    new_check(
      paste0(prefix, "_safety_stock_monotonic_in_service_level"),
      all(safety_ordered$monotone),
      sum(safety_ordered$monotone),
      nrow(safety_ordered)
    )
  )

  lead_time_ordered <- frame %>%
    dplyr::group_by(store_id, service_level) %>%
    dplyr::arrange(lead_time_days, .by_group = TRUE) %>%
    dplyr::summarise(
      monotone = all(diff(expected_lead_time_demand) > 0),
      .groups = "drop"
    )

  checks <- rbind(
    checks,
    new_check(
      paste0(prefix, "_lead_time_demand_monotonic_in_lead_time"),
      all(lead_time_ordered$monotone),
      sum(lead_time_ordered$monotone),
      nrow(lead_time_ordered)
    )
  )

  checks
}

validate_scenario_families <- function(loaded, checks) {
  scenarios <- loaded$data$scenarios
  forecast_scenarios <- loaded$data$forecast_scenarios
  validation_results <- loaded$data$validation_results
  forecast_errors <- loaded$data$forecast_errors

  historical_checks <- validate_scenario_family(
    scenarios,
    "historical",
    "mean_daily_demand",
    "std_daily_demand"
  )

  forecast_checks <- validate_scenario_family(
    forecast_scenarios,
    "forecast",
    "bias_adjusted_daily_demand",
    "residual_std"
  )

  checks$add(
    "forecast_level_is_bias_corrected",
    within_tolerance(
      forecast_scenarios$model_daily_demand + forecast_scenarios$bias,
      forecast_scenarios$bias_adjusted_daily_demand,
      RELATIVE_TOLERANCE
    ),
    format_value(
      max(relative_difference(
        forecast_scenarios$model_daily_demand + forecast_scenarios$bias,
        forecast_scenarios$bias_adjusted_daily_demand
      )),
      12
    ),
    paste("<=", RELATIVE_TOLERANCE)
  )

  tuned <- validation_results %>%
    dplyr::select(
      store_id,
      tuned_model = model,
      tuned_configuration = configuration
    )

  scenario_configuration <- forecast_scenarios %>%
    dplyr::distinct(store_id, model, configuration) %>%
    dplyr::left_join(tuned, by = "store_id")

  configuration_matches <- scenario_configuration$model ==
    scenario_configuration$tuned_model &
    scenario_configuration$configuration ==
      scenario_configuration$tuned_configuration

  checks$add(
    "forecast_scenarios_use_tuned_configuration",
    all(configuration_matches),
    sum(configuration_matches),
    nrow(scenario_configuration)
  )

  error_join <- forecast_errors %>%
    dplyr::select(store_id, error_rmse = rmse, error_mape = mape_percent) %>%
    dplyr::inner_join(
      validation_results %>%
        dplyr::select(
          store_id,
          validation_rmse = rmse,
          validation_mape = mape_percent
        ),
      by = "store_id"
    )

  checks$add(
    "forecast_error_matches_validation",
    within_tolerance(
      error_join$error_rmse,
      error_join$validation_rmse,
      METRIC_TOLERANCE
    ) &&
      within_tolerance(
        error_join$error_mape,
        error_join$validation_mape,
        METRIC_TOLERANCE
      ),
    format_value(
      max(relative_difference(
        error_join$error_rmse,
        error_join$validation_rmse
      )),
      12
    ),
    paste("<=", METRIC_TOLERANCE)
  )

  rbind(historical_checks, forecast_checks)
}

