# Scenario summaries
# -------------------------------------------------------------------

summarise_scenarios <- function(frame) {
  frame %>%
    dplyr::group_by(lead_time_days, service_level) %>%
    dplyr::summarise(
      stores = dplyr::n_distinct(store_id),
      average_reorder_point = mean(reorder_point),
      maximum_reorder_point = max(reorder_point),
      average_safety_stock = mean(safety_stock),
      .groups = "drop"
    ) %>%
    dplyr::arrange(lead_time_days, service_level)
}

baseline_scenario <- function(frame, columns) {
  frame %>%
    dplyr::filter(
      lead_time_days == PLANNING_LEAD_TIME_DAYS,
      service_level == PLANNING_SERVICE_LEVEL
    ) %>%
    dplyr::select(dplyr::all_of(columns)) %>%
    dplyr::arrange(store_id)
}

# -------------------------------------------------------------------
# Phase 13 reconciliation
# -------------------------------------------------------------------

reconcile_phase13 <- function(loaded, store_analysis, checks) {
  insights <- loaded$data$insights
  validation_results <- loaded$data$validation_results
  scenarios <- loaded$data$scenarios
  forecast_scenarios <- loaded$data$forecast_scenarios

  highest_demand <- store_analysis %>%
    dplyr::slice_max(order_by = mean_daily_demand, n = 1, with_ties = FALSE)

  highest_variability <- store_analysis %>%
    dplyr::slice_max(
      order_by = coefficient_of_variation,
      n = 1,
      with_ties = FALSE
    )

  lowest_rmse <- validation_results %>%
    dplyr::slice_min(order_by = rmse, n = 1, with_ties = FALSE)

  lowest_mape <- validation_results %>%
    dplyr::slice_min(order_by = mape_percent, n = 1, with_ties = FALSE)

  largest_bias <- loaded$data$forecast_errors %>%
    dplyr::slice_max(order_by = bias, n = 1, with_ties = FALSE)

  historical_baseline <- baseline_scenario(
    scenarios,
    c("store_id", "reorder_point")
  ) %>%
    dplyr::rename(historical_reorder_point = reorder_point)

  forecast_baseline <- baseline_scenario(
    forecast_scenarios,
    c("store_id", "reorder_point")
  ) %>%
    dplyr::rename(forecast_reorder_point = reorder_point)

  expected <- rbind(
    data.frame(
      insight_type = "highest_average_demand",
      store_id = highest_demand$store_id,
      metric = "mean_daily_demand",
      r_value = highest_demand$mean_daily_demand,
      stringsAsFactors = FALSE
    ),
    data.frame(
      insight_type = "highest_relative_variability",
      store_id = highest_variability$store_id,
      metric = "coefficient_of_variation",
      r_value = highest_variability$coefficient_of_variation,
      stringsAsFactors = FALSE
    ),
    data.frame(
      insight_type = "lowest_validation_rmse",
      store_id = lowest_rmse$store_id,
      metric = "validation_rmse",
      r_value = lowest_rmse$rmse,
      stringsAsFactors = FALSE
    ),
    data.frame(
      insight_type = "lowest_relative_validation_error",
      store_id = lowest_mape$store_id,
      metric = "validation_mape_percent",
      r_value = lowest_mape$mape_percent,
      stringsAsFactors = FALSE
    ),
    data.frame(
      insight_type = "systematic_bias",
      store_id = largest_bias$store_id,
      metric = "mean_forecast_bias",
      r_value = largest_bias$bias,
      stringsAsFactors = FALSE
    ),
    historical_baseline %>%
      dplyr::transmute(
        insight_type = "inventory_scenario",
        store_id = store_id,
        metric = "reorder_point",
        r_value = historical_reorder_point
      ),
    forecast_baseline %>%
      dplyr::transmute(
        insight_type = "forecast_inventory_scenario",
        store_id = store_id,
        metric = "reorder_point",
        r_value = forecast_reorder_point
      )
  )

  published <- insights %>%
    dplyr::select(
      insight_type,
      store_id,
      metric,
      phase13_value = value
    )

  reconciliation <- dplyr::inner_join(
    published,
    expected,
    by = c("insight_type", "store_id")
  )

  reconciliation$metric_matches <- reconciliation$metric.x ==
    reconciliation$metric.y
  reconciliation$relative_difference <- relative_difference(
    reconciliation$r_value,
    reconciliation$phase13_value
  )
  reconciliation$match <- reconciliation$metric_matches &
    reconciliation$relative_difference <= RELATIVE_TOLERANCE

  reconciliation <- reconciliation %>%
    dplyr::transmute(
      insight_type,
      store_id,
      metric = metric.x,
      phase13_value,
      r_value,
      relative_difference,
      match
    ) %>%
    dplyr::arrange(insight_type, store_id)

  checks$add(
    "phase13_insight_types_complete",
    setequal(unique(insights$insight_type), INSIGHT_TYPES),
    describe_vector(sort(unique(insights$insight_type))),
    describe_vector(INSIGHT_TYPES)
  )

  checks$add(
    "phase13_insight_rows_reconciled",
    nrow(reconciliation) == nrow(insights),
    nrow(reconciliation),
    nrow(insights)
  )

  for (insight_type in INSIGHT_TYPES) {
    rows <- reconciliation[reconciliation$insight_type == insight_type, ]

    checks$add(
      paste0("phase13_", insight_type, "_reconciles"),
      nrow(rows) > 0L && all(rows$match),
      sum(rows$match),
      nrow(rows)
    )
  }

  canonical <- data.frame(
    insight_type = names(CANONICAL_METRICS),
    canonical_metric = unname(CANONICAL_METRICS),
    stringsAsFactors = FALSE
  )

  labelled <- published %>%
    dplyr::left_join(canonical, by = "insight_type")

  checks$add(
    "phase13_metric_names_reconcile",
    all(!is.na(labelled$canonical_metric)) &&
      all(labelled$metric == labelled$canonical_metric),
    sum(labelled$metric == labelled$canonical_metric),
    nrow(labelled)
  )

  store_analysis_consistency <- reconciliation[
    reconciliation$insight_type == "highest_average_demand",
  ]

  # A published insight that names a store R did not select cannot be joined,
  # so the row count is reported instead of assuming a match exists.
  matched_store <- if (nrow(store_analysis_consistency) == 1L) {
    as.character(store_analysis_consistency$store_id)
  } else {
    paste0(nrow(store_analysis_consistency), " reconciled row(s)")
  }

  checks$add(
    "phase13_highest_demand_store_reconciles",
    nrow(store_analysis_consistency) == 1L &&
      store_analysis_consistency$store_id == highest_demand$store_id &&
      store_analysis_consistency$match,
    matched_store,
    as.character(highest_demand$store_id)
  )

  list(
    reconciliation = reconciliation,
    highest_demand = highest_demand,
    highest_variability = highest_variability
  )
}

# -------------------------------------------------------------------
# Phase 12 metric recomputation (tidymodels/yardstick)
# -------------------------------------------------------------------

recompute_validation_metrics <- function(loaded, checks) {
  predictions <- loaded$data$predictions
  forecast_errors <- loaded$data$forecast_errors
  validation_results <- loaded$data$validation_results

  checks$add(
    "prediction_scopes_recognised",
    all(unique(predictions$scope) %in% c("cv_fold", "validation")),
    describe_vector(sort(unique(predictions$scope))),
    "cv_fold|validation"
  )

  checks$add(
    "test_period_excluded",
    !any(predictions$scope == "test"),
    sum(predictions$scope == "test"),
    0
  )

  validation_predictions <- predictions %>%
    dplyr::filter(scope == "validation")

  checks$add(
    "validation_predictions_present",
    nrow(validation_predictions) > 0L,
    nrow(validation_predictions),
    "> 0"
  )

  metrics <- validation_predictions %>%
    dplyr::group_by(store_id) %>%
    dplyr::summarise(
      observations = dplyr::n(),
      rmse = yardstick::rmse_vec(actual, predicted),
      mae = yardstick::mae_vec(actual, predicted),
      # yardstick reports MAPE as a percentage, matching the Phase 12 field.
      mape_percent = yardstick::mape_vec(actual, predicted),
      .groups = "drop"
    ) %>%
    dplyr::arrange(store_id)

  reported <- validation_results %>%
    dplyr::select(
      store_id,
      reported_rmse = rmse,
      reported_mape_percent = mape_percent
    ) %>%
    dplyr::inner_join(
      forecast_errors %>%
        dplyr::select(store_id, error_observations = observations),
      by = "store_id"
    )

  reconciliation <- metrics %>%
    dplyr::left_join(reported, by = "store_id")

  reconciliation$rmse_relative_difference <- relative_difference(
    reconciliation$rmse,
    reconciliation$reported_rmse
  )
  reconciliation$mape_relative_difference <- relative_difference(
    reconciliation$mape_percent,
    reconciliation$reported_mape_percent
  )

  checks$add(
    "recomputed_metrics_cover_all_stores",
    nrow(metrics) == nrow(validation_results) &&
      setequal(metrics$store_id, validation_results$store_id),
    nrow(metrics),
    nrow(validation_results)
  )

  checks$add(
    "recomputed_observations_reconcile",
    all(reconciliation$observations == reconciliation$error_observations),
    describe_vector(reconciliation$observations),
    describe_vector(reconciliation$error_observations)
  )

  checks$add(
    "recomputed_rmse_reconciles_with_phase12",
    within_tolerance(
      reconciliation$rmse,
      reconciliation$reported_rmse,
      METRIC_TOLERANCE
    ),
    format_value(max(reconciliation$rmse_relative_difference), 12),
    paste("<=", METRIC_TOLERANCE)
  )

  checks$add(
    "recomputed_mape_reconciles_with_phase12",
    within_tolerance(
      reconciliation$mape_percent,
      reconciliation$reported_mape_percent,
      METRIC_TOLERANCE
    ),
    format_value(max(reconciliation$mape_relative_difference), 12),
    paste("<=", METRIC_TOLERANCE)
  )

  reconciliation
}

# -------------------------------------------------------------------
# Densification reconciliation
# -------------------------------------------------------------------

reconcile_densification <- function(loaded, checks) {
  densification <- loaded$data$densification
  demand <- loaded$data$demand

  joined <- demand %>%
    dplyr::select(store_id, training_days) %>%
    dplyr::inner_join(
      densification %>%
        dplyr::select(
          store_id,
          observed_days,
          densified_days,
          synthetic_days
        ),
      by = "store_id"
    )

  checks$add(
    "densification_matches_training_days",
    all(joined$training_days == joined$densified_days),
    describe_vector(joined$densified_days),
    describe_vector(joined$training_days)
  )

  checks$add(
    "densification_totals_reconcile",
    sum(densification$densified_days) == sum(demand$training_days),
    sum(densification$densified_days),
    sum(demand$training_days)
  )

  checks$add(
    "synthetic_days_measured_consistently",
    all(
      densification$densified_days - densification$observed_days ==
        densification$synthetic_days
    ),
    sum(densification$synthetic_days),
    "densified - observed == synthetic"
  )

  checks$add(
    "zero_filled_days_are_minimal",
    sum(densification$synthetic_days) == 1L,
    sum(densification$synthetic_days),
    1
  )

  joined
}

