build_plots <- function(
  store_analysis,
  scenarios,
  forecast_scenarios,
  plot_dir
) {
  written <- character()

  demand_plot <- ggplot2::ggplot(
    store_analysis,
    ggplot2::aes(x = factor(store_id), y = mean_daily_demand)
  ) +
    ggplot2::geom_col() +
    ggplot2::labs(
      title = "Average Daily Demand by Store",
      subtitle = "Densified training store-day series (Phases 11-13 basis)",
      x = "Store",
      y = "Mean Daily Demand"
    ) +
    ggplot2::theme_minimal()

  suppressMessages(
    ggplot2::ggsave(
      filename = file.path(plot_dir, "average_daily_demand_by_store.png"),
      plot = demand_plot,
      width = 8,
      height = 5,
      dpi = 150
    )
  )
  written <- c(written, "average_daily_demand_by_store.png")

  variability_plot <- ggplot2::ggplot(
    store_analysis,
    ggplot2::aes(x = factor(store_id), y = coefficient_of_variation)
  ) +
    ggplot2::geom_col() +
    ggplot2::labs(
      title = "Relative Demand Variability by Store",
      subtitle = "Coefficient of variation (standard deviation / mean)",
      x = "Store",
      y = "Coefficient of Variation"
    ) +
    ggplot2::theme_minimal()

  suppressMessages(
    ggplot2::ggsave(
      filename = file.path(plot_dir, "demand_variability_by_store.png"),
      plot = variability_plot,
      width = 8,
      height = 5,
      dpi = 150
    )
  )
  written <- c(written, "demand_variability_by_store.png")

  scenario_plot <- scenarios %>%
    ggplot2::ggplot(
      ggplot2::aes(
        x = lead_time_days,
        y = reorder_point,
        group = service_level,
        linetype = factor(service_level)
      )
    ) +
    ggplot2::geom_line() +
    ggplot2::geom_point() +
    ggplot2::facet_wrap(~ store_id) +
    ggplot2::labs(
      title = "Historical Scenario Reorder Points by Lead Time and Service Level",
      x = "Lead Time (Days)",
      y = "Reorder Point",
      linetype = "Service Level"
    ) +
    ggplot2::theme_minimal()

  suppressMessages(
    ggplot2::ggsave(
      filename = file.path(plot_dir, "inventory_reorder_point_scenarios.png"),
      plot = scenario_plot,
      width = 10,
      height = 7,
      dpi = 150
    )
  )
  written <- c(written, "inventory_reorder_point_scenarios.png")

  comparison_plot <- dplyr::bind_rows(
    scenarios %>%
      dplyr::mutate(family = "historical variability"),
    forecast_scenarios %>%
      dplyr::mutate(family = "forecast residual error")
  ) %>%
    ggplot2::ggplot(
      ggplot2::aes(
        x = lead_time_days,
        y = reorder_point,
        colour = family,
        linetype = factor(service_level)
      )
    ) +
    ggplot2::geom_line() +
    ggplot2::geom_point() +
    ggplot2::facet_wrap(~ store_id) +
    ggplot2::labs(
      title = "Reorder-Point Scenarios: Historical Variability vs Forecast Error",
      x = "Lead Time (Days)",
      y = "Reorder Point",
      colour = "Uncertainty input",
      linetype = "Service Level"
    ) +
    ggplot2::theme_minimal()

  suppressMessages(
    ggplot2::ggsave(
      filename = file.path(plot_dir, "inventory_scenario_family_comparison.png"),
      plot = comparison_plot,
      width = 11,
      height = 7,
      dpi = 150
    )
  )
  written <- c(written, "inventory_scenario_family_comparison.png")

  written
}

verify_plots <- function(plot_dir, written, checks) {
  paths <- file.path(plot_dir, written)
  sizes <- file.info(paths)$size

  checks$add(
    "plots_written",
    all(file.exists(paths)),
    sum(file.exists(paths)),
    length(paths)
  )

  checks$add(
    "plots_non_empty",
    all(!is.na(sizes) & sizes > 0),
    format_value(min(sizes, na.rm = TRUE), 0),
    "> 0 bytes"
  )

  checks$add(
    "plots_regenerated_from_analytical_data",
    identical(sort(written), sort(PLOT_FILES)),
    describe_vector(sort(written)),
    describe_vector(sort(PLOT_FILES))
  )

  invisible(paths)
}

