write_findings <- function(paths, results) {
  reconciliation <- results$reconciliation
  metrics <- results$metrics

  historical_baseline <- results$historical_baseline
  forecast_baseline <- results$forecast_baseline

  store_notes <- reconciliation %>%
    dplyr::filter(insight_type == "highest_average_demand")
  variability_notes <- reconciliation %>%
    dplyr::filter(insight_type == "highest_relative_variability")

  findings <- c(
    "Phase 14 - R Analysis Findings",
    "",
    paste("Generated:", format(Sys.time(), tz = "UTC", usetz = TRUE)),
    paste("R:", R.version.string),
    paste("Input directory:", paths$input_dir),
    "",
    "Evidence basis:",
    paste0(
      "- Training store-days reconciled with Phase 13: ",
      sum(results$densification$densified_days),
      " (observed ",
      sum(results$densification$observed_days),
      ", zero-filled ",
      sum(results$densification$synthetic_days),
      ")"
    ),
    paste(
      "- Inventory scenarios analysed per family:",
      nrow(results$scenarios),
      "historical and",
      nrow(results$forecast_scenarios),
      "forecast-error"
    ),
    paste(
      "- Phase 12 validation forecasts independently recomputed in R:",
      sum(metrics$observations)
    ),
    "",
    "Historical demand:",
    paste(
      "- Highest average daily demand store:",
      results$highest_demand$store_id
    ),
    paste(
      "- Mean daily demand:",
      format_value(results$highest_demand$mean_daily_demand, 3)
    ),
    paste(
      "- Highest relative variability store:",
      results$highest_variability$store_id
    ),
    paste(
      "- Coefficient of variation:",
      format_value(results$highest_variability$coefficient_of_variation, 6)
    ),
    "",
    "Cross-language verification:",
    paste(
      "- Recomputed RMSE vs Phase 12 maximum relative difference:",
      format_value(max(metrics$rmse_relative_difference), 10)
    ),
    paste(
      "- Recomputed MAPE vs Phase 12 maximum relative difference:",
      format_value(max(metrics$mape_relative_difference), 10)
    ),
    paste(
      "- Phase 13 insight rows reconciled:",
      sum(reconciliation$match),
      "of",
      nrow(reconciliation)
    ),
    "",
    "Planning scenario (14-day lead time, 95% service level):",
    paste(
      "- Historical-variability reorder points:",
      paste(
        paste0(
          historical_baseline$store_id,
          " = ",
          format_value(historical_baseline$reorder_point, 0)
        ),
        collapse = "; "
      )
    ),
    paste(
      "- Forecast-error reorder points:",
      paste(
        paste0(
          forecast_baseline$store_id,
          " = ",
          format_value(forecast_baseline$reorder_point, 0)
        ),
        collapse = "; "
      )
    ),
    "",
    "Quality:",
    paste(
      "- Quality checks passed:",
      sum(results$quality$passed),
      "of",
      nrow(results$quality)
    ),
    paste(
      "- Store-level consistency with Phase 13:",
      ifelse(all(reconciliation$match), "verified", "NOT verified")
    ),
    "",
    "Interpretation:",
    paste(
      "- R independently reproduces the Phase 13 store-level findings: store",
      store_notes$store_id,
      "leads on average demand and store",
      variability_notes$store_id,
      "on relative variability."
    ),
    paste(
      "- Recomputed validation metrics agree with the Phase 12 artifacts, so",
      "the forecast evidence is verified in a second language."
    ),
    paste(
      "- Mean absolute error is reported here as additional evidence; Phase 12",
      "did not publish it, so it is an R-derived statistic rather than a",
      "reconciliation."
    ),
    "",
    "Limitations:",
    "- Inventory values are planning scenarios, not operational requirements.",
    "- The dataset provides no supplier lead times, service-level requirements,",
    "  holding costs, ordering costs, stockout costs, current stock, purchase",
    "  orders or warehouse constraints.",
    "- Store 4 has 60 training days and one cross-validation fold, so its",
    "  variability and forecast-error estimates rest on fewer observations",
    "  than the other stores.",
    "- R does not replace or retrain the validated Python forecasting models.",
    "",
    "Reproducibility:",
    "- Regenerate with: Rscript r/r_analysis.R",
    "- Render the report with:",
    "  Rscript -e \"rmarkdown::render('r/r_analysis_report.Rmd')\""
  )

  writeLines(findings, file.path(paths$output_dir, "r_analysis_findings.txt"))
  findings
}

# -------------------------------------------------------------------
# Quality report
# -------------------------------------------------------------------

write_quality_report <- function(report, paths) {
  readr::write_csv(
    report,
    file.path(paths$output_dir, "r_analysis_quality_report.csv")
  )
  report
}

gate_quality_report <- function(report) {
  failed <- report[!report$passed, , drop = FALSE]

  if (nrow(failed) > 0L) {
    message(
      "Failed quality checks: ",
      paste(failed$check, collapse = ", ")
    )
    stop(
      paste0(
        "Phase 14 R analysis failed validation: ",
        nrow(failed),
        " of ",
        nrow(report),
        " checks failed. See r_analysis_quality_report.csv."
      ),
      call. = FALSE
    )
  }

  invisible(TRUE)
}

# -------------------------------------------------------------------
# Main workflow
# -------------------------------------------------------------------

main <- function() {
  paths <- resolve_paths(find_project_root())

  dir.create(paths$output_dir, recursive = TRUE, showWarnings = FALSE)
  dir.create(paths$plot_dir, recursive = TRUE, showWarnings = FALSE)

  packages <- check_required_packages()

  suppressPackageStartupMessages({
    library(tidyverse)
    library(yardstick)
  })

  checks <- check_collector()

  loaded <- load_inputs(paths$input_dir)
  inputs_ready <- validate_inputs(loaded, checks)

  if (!isTRUE(inputs_ready)) {
    report <- write_quality_report(checks$frame(), paths)
    record_environment(paths, packages)
    gate_quality_report(report)
  }

  scenario_checks <- validate_scenario_families(loaded, checks)

  store_analysis <- build_store_analysis(
    loaded$data$demand,
    loaded$data$variability
  )

  scenarios <- loaded$data$scenarios
  forecast_scenarios <- loaded$data$forecast_scenarios

  scenario_summary <- summarise_scenarios(scenarios)
  forecast_scenario_summary <- summarise_scenarios(forecast_scenarios)

  historical_baseline <- baseline_scenario(
    scenarios,
    c(
      "store_id",
      "model",
      "configuration",
      "mean_daily_demand",
      "std_daily_demand",
      "expected_lead_time_demand",
      "safety_stock",
      "reorder_point"
    )
  )

  forecast_baseline <- baseline_scenario(
    forecast_scenarios,
    c(
      "store_id",
      "model",
      "configuration",
      "model_daily_demand",
      "bias",
      "bias_adjusted_daily_demand",
      "residual_std",
      "rmse",
      "expected_lead_time_demand",
      "safety_stock",
      "reorder_point"
    )
  )

  reconciliation_results <- reconcile_phase13(loaded, store_analysis, checks)

  metrics <- recompute_validation_metrics(loaded, checks)

  densification <- reconcile_densification(loaded, checks)

  written_plots <- build_plots(
    store_analysis,
    scenarios,
    forecast_scenarios,
    paths$plot_dir
  )

  verify_plots(paths$plot_dir, written_plots, checks)

  quality <- combine_checks(
    checks$frame(),
    scenario_checks,
    new_check(
      "historical_and_forecast_scenarios_share_store_set",
      setequal(scenarios$store_id, forecast_scenarios$store_id),
      describe_vector(sort(unique(forecast_scenarios$store_id))),
      describe_vector(sort(unique(scenarios$store_id)))
    )
  )

  readr::write_csv(
    store_analysis,
    file.path(paths$output_dir, "r_store_analysis.csv")
  )

  readr::write_csv(
    scenario_summary,
    file.path(paths$output_dir, "r_inventory_scenario_summary.csv")
  )

  readr::write_csv(
    forecast_scenario_summary,
    file.path(paths$output_dir, "r_forecast_inventory_scenario_summary.csv")
  )

  readr::write_csv(
    historical_baseline,
    file.path(paths$output_dir, "r_baseline_inventory_scenario.csv")
  )

  readr::write_csv(
    forecast_baseline,
    file.path(paths$output_dir, "r_baseline_forecast_inventory_scenario.csv")
  )

  consistency <- reconciliation_results$reconciliation %>%
    dplyr::filter(
      insight_type %in% c(
        "highest_average_demand",
        "highest_relative_variability"
      )
    ) %>%
    dplyr::transmute(
      check = insight_type,
      phase_13_store = store_id,
      r_store = store_id,
      match
    )

  readr::write_csv(
    consistency,
    file.path(paths$output_dir, "r_phase13_consistency.csv")
  )

  readr::write_csv(
    reconciliation_results$reconciliation,
    file.path(paths$output_dir, "r_phase13_reconciliation.csv")
  )

  readr::write_csv(
    metrics,
    file.path(paths$output_dir, "r_metric_reconciliation.csv")
  )

  environment <- record_environment(paths, packages)

  write_quality_report(quality, paths)

  gate_quality_report(quality)

  results <- list(
    paths = paths,
    packages = packages,
    environment = environment,
    inputs = loaded$data,
    store_analysis = store_analysis,
    scenarios = scenarios,
    forecast_scenarios = forecast_scenarios,
    scenario_summary = scenario_summary,
    forecast_scenario_summary = forecast_scenario_summary,
    historical_baseline = historical_baseline,
    forecast_baseline = forecast_baseline,
    reconciliation = reconciliation_results$reconciliation,
    highest_demand = reconciliation_results$highest_demand,
    highest_variability = reconciliation_results$highest_variability,
    metrics = metrics,
    densification = densification,
    quality = quality,
    plots = written_plots
  )

  results$findings <- write_findings(paths, results)

  cat("Phase 14 R analysis completed successfully.\n")
  cat("Quality checks passed:", sum(quality$passed), "of", nrow(quality), "\n")
  cat(
    "R output directory:",
    normalizePath(paths$output_dir, winslash = "/"),
    "\n"
  )
  cat(
    "Render the report with (from the repository root):",
    paste0(
      "Rscript -e \"rmarkdown::render('r/r_analysis_report.Rmd', ",
      "output_dir = file.path(getwd(), 'data', 'analysis', 'r'))\"\n"
    )
  )

  invisible(results)
}

# Invoked only when this file is executed as a script. When the R Markdown
# report sources this file, it calls main() itself so the report and the
# script verify the same evidence.
if (sys.nframe() == 0L) {
  main()
}
